def transform(df):
    df['value'] = df['value'].apply(
        lambda x: float(x.replace('$', '').replace(',', '')) if isinstance(x, str) and 'k' not in x and ',' not in x and '$' not in x else None
    )
    df['value'] = df['value'].apply(
        lambda x: float(x.replace('k', '000')) if isinstance(x, str) and 'k' in x else x
    )
    df['value'] = df['value'].apply(
        lambda x: float(x.replace(' ', '')) if isinstance(x, str) and ' ' in x else x
    )
    return df
